VAR
    Overload_Timer : TON;
END_VAR

// 125% of 41.5A = 51.875A
// Using the timer to debounce the alarm slightly (e.g., 2 seconds) to avoid nuisance trips
Overload_Timer(IN := (Motor_Current > 51.875), PT := T#2S);

IF Overload_Timer.Q THEN
    Overload_Alarm := TRUE;
END_IF;

IF Fault_Reset THEN
    Overload_Alarm := FALSE;
END_IF;

